record.field:
{
    "type": "object",
    "properties": {
        "menu_id": {
            "type": "number",
            "description": "The id of the menu linked to the action to execute."
        },
        "action_type": {
            "type": "string",
            "description": "The type of the action to execute",
            "enum": ["ir.actions.client", "ir.actions.report"]
        }
    },
    "required": ["menu_id", "action_type"]
}

{
    "type": "object",
    "properties": {
        "question": {
            "type": "string",
            "description": "The question to show the user. Must be a complete, self-contained question"
        },
        "choices": {
            "type": "array",
            "description": "Between two and four meaningful clickable choices to offer.",
            "items": {
                "type": "string",
                "description": "Short answer shown to the user and sent back when selected."
            }
        },
        "multi_select": {
            "type": "boolean",
            "description": "Allow the user to pick more than one choice. Set to false if a single choice is required for the question."
        },
        "allow_free_text": {
            "type": "boolean",
            "description": "Whether the user can provide an unlisted answer. Explicitly set to true in most calls; set to false only for a complete, fixed set of answers."
        }
    },
    "required": ["question", "choices", "multi_select", "allow_free_text"]
}

{
    "type": "object",
    "properties": {
        "menu_ids": {
            "type": "array",
            "items": {"type": "number"},
            "description": "List of menu IDs to get details for (available in menu data context)"
        },
        "include_model_fields": {
            "type": "boolean",
            "description": "Whether to include the fields of the models of the menu"
        }
    },
    "required": ["menu_ids", "include_model_fields"]
}

{
    "type": "object",
    "properties": {
        "model_name": {
            "type": "string",
            "description": "Technical model name (e.g., 'sale.order', 'product.product', 'res.partner')"
        },
        "include_description": {
            "type": "boolean",
            "description": "Whether to include the fields descriptions (default: true)"
        }
    },
    "required": ["model_name"]
}

{
    "type": "object",
    "properties": {
        "menu_id": {
            "type": "number",
            "description": "The id of the menu to open"
        },
        "model_name": {
            "type": "string",
            "description": "The technical model name (eg. 'res.users')"
        },
        "selected_filters": {
            "type": "array",
            "description": "List of active filters. Can include both predefined search filters and specific date range configurations. Use [] for no filters",
            "items": {
                "anyOf": [
                    {
                        "type": "string",
                        "description": "The technical name of a predefined filter (e.g., 'my_favorites' or 'active'). Must match a name in the menu's search view's available filters"
                    },
                    {
                        "type": "object",
                        "description": "Custom date range configuration",
                        "properties": {
                            "field_name": {
                                "type": "string",
                                "description": "The technical name of the date field (e.g., 'date_order')"
                            },
                            "selected_periods": {
                                "type": "array",
                                "description": "List of relative periods (e.g., ['month', 'year-1'])",
                                "items": {
                                    "type": "string",
                                    "description": "Pattern: 'month', 'year', 'month±N', 'year±N', 'first_quarter', 'second_quarter', 'third_quarter', 'fourth_quarter' or 'custom_...' (where N restrictions and custom_... patterns are found in the menu's search view)"
                                }
                            }
                        },
                        "required": ["field_name", "selected_periods"]
                    }
                ]
            }
        },
        "selected_groupbys": {
            "type": "array",
            "description": "Ordered list of fields or date intervals objects to group by. Prioritize fields in the menu's search views' groupby fields. Any other groupable field can be used.  Use [] for no grouping.",
            "items": {
                "anyOf": [
                    {
                        "type": "string",
                        "description": "The technical name of the field to group by"
                    },
                    {
                        "type": "object",
                        "description": "Date interval grouping object",
                        "properties": {
                            "field_name": {
                                "type": "string",
                                "description": "The technical name of the date field"
                            },
                            "intervals": {
                                "type": "array",
                                "description": "List of intervals to group by",
                                "items": {
                                    "type": "string",
                                    "description": "Interval name",
                                    "enum": ["day", "week", "month", "quarter", "year"]
                                }
                            }
                        },
                        "required": ["field_name", "intervals"]
                    }
                ]
            }
        },
        "search": {
            "type": "array",
            "description": "Simulates typing into the search bar. Use this for quick text lookups on specific fields. Use [] for no search",
            "items": {
                "type": "object",
                "properties": {
                    "search_field": {
                        "type": "string",
                        "description": "Technical name of the field to search (e.g., 'partner_id', 'name'). Must be a searchable field"
                    },
                    "value": {
                        "type": "string",
                        "description": "Text value to search for"
                    }
                },
                "required": ["search_field", "value"]
            }
        },
        "custom_domain": {
            "type": "string",
            "description": "Optional odoo domain, to use when search view elements are insufficient."
        }
    },
    "required": ["menu_id", "model_name", "selected_filters", "selected_groupbys", "search"]
}

