{
    "type": "object",
    "properties": {
        "menu_id": {
            "type": "number",
            "description": "The id of the menu to open (preferably 'Reporting' app menu)"
        },
        "model_name": {
            "type": "string",
            "description": "The technical model name (eg. 'res.users')"
        },
        "selected_filters": {
            "type": "array",
            "description": "List of active filters. Can include both predefined search filters and specific date range configurations. Use [] for no filters",
            "items": {
                "anyOf": [
                    {
                        "type": "string",
                        "description": "The technical name of a predefined filter (e.g., 'my_favorites' or 'active'). Must match a name in the menu's search view's available filters"
                    },
                    {
                        "type": "object",
                        "description": "Custom date range configuration",
                        "properties": {
                            "field_name": {
                                "type": "string",
                                "description": "The technical name of the date field (e.g., 'date_order')"
                            },
                            "selected_periods": {
                                "type": "array",
                                "description": "List of relative periods (e.g., ['month', 'year-1'])",
                                "items": {
                                    "type": "string",
                                    "description": "Pattern: 'month', 'year', 'month±N', 'year±N', 'first_quarter', 'second_quarter', 'third_quarter', 'fourth_quarter' or 'custom_...' (where N restrictions and custom_... patterns are found in the menu's search view)"
                                }
                            }
                        },
                        "required": ["field_name", "selected_periods"]
                    }
                ]
            }
        },
        "row_groupbys": {
            "type": "array",
            "description": "Ordered list of fields or date intervals objects to group the rows by. Prefer fields in the menu's search views' groupby fields. Any other groupable field can be used.  Use [] for no grouping.",
            "items": {
                "anyOf": [
                    {
                        "type": "string",
                        "description": "The technical name of the field to group by"
                    },
                    {
                        "type": "object",
                        "description": "Date interval grouping object",
                        "properties": {
                            "field_name": {
                                "type": "string",
                                "description": "The technical name of the date field"
                            },
                            "intervals": {
                                "type": "array",
                                "description": "List of intervals to group by",
                                "items": {
                                    "type": "string",
                                    "description": "Interval name",
                                    "enum": ["day", "week", "month", "quarter", "year"]}
                            }
                        },
                        "required": ["field_name", "intervals"]
                    }
                ]
            }
        },
        "col_groupbys": {
            "type": "array",
            "description": "Ordered list of fields or date intervals objects to group the columns by. Prefer fields in the menu's search views' groupby fields. Any other groupable field can be used.  Use [] for no grouping.",
            "items": {
                "anyOf": [
                    {
                        "type": "string",
                        "description": "The technical name of the field to group by"
                    },
                    {
                        "type": "object",
                        "description": "Date interval grouping object",
                        "properties": {
                            "field_name": {
                                "type": "string",
                                "description": "The technical name of the date field"
                            },
                            "intervals": {
                                "type": "array",
                                "description": "List of intervals to group by",
                                "items": {
                                    "type": "string",
                                    "description": "Interval name",
                                    "enum": ["day", "week", "month", "quarter", "year"]}
                            }
                        },
                        "required": ["field_name", "intervals"]
                    }
                ]
            }
        },
        "measures": {
            "type": "array",
            "description": "List of quantitative measures to display. Refer to 'compute report measures' for valid names or ise '__count' for record count. Order affects column sequence",
            "items": {
                "type": "object",
                "properties": {
                    "name": {
                        "type": "string",
                        "description": "Technical field name (e.g., 'amount_total') or '__count'"
                    },
                    "order": {
                        "type": "string",
                        "enum": ["desc", "asc"],
                        "description": "Sorting direction. Note: Only the first measure in the array with an 'order' will define the table's sort column"
                    }
                },
                "required": ["name"]
            }
        },
        "search": {
            "type": "array",
            "description": "Simulates typing into the search bar. Use this for quick text lookups on specific fields. Use [] for no search",
            "items": {
                "type": "object",
                "properties": {
                    "search_field": {
                        "type": "string",
                        "description": "Technical name of the field to search (e.g., 'partner_id', 'name'). Must be a searchable field"
                    },
                    "value": {
                        "type": "string",
                        "description": "Text value to search for"
                    }
                },
                "required": ["search_field", "value"]
            }
        },
        "custom_domain": {
            "type": "string",
            "description": "Optional odoo domain, to use when search view elements are insufficient."
        }
    },
    "required": ["menu_id", "model_name", "selected_filters", "row_groupbys", "col_groupbys", "measures", "search"]
}

