}

{
    "type": "object",
    "properties": {
        "action_id": {
            "type": "number",
            "description": "Action ID - the id of the action linked to a menu or available in the current view context."
        },
        "model_name": {
            "type": "string",
            "description": "Model name - must match the action's model"
        }
    },
    "required": ["action_id", "model_name"]
}

{
    "type": "object",
    "properties": {
        "model_name": {
            "type": "string",
            "description": "The technical model name (eg. 'res.users') of the current view"
        },
        "remove_facets": {
            "type": "array",
            "items": {
                "type": "number",
                "description": "Id of the facet to remove. Must be in the facets of the 'Current Session'"
            },
            "description": "List of ids of facets groups to remove, where each facet represents a group of related filters, groupbys, or search terms. Use this when: (1) User wants to 'switch' or 'change' from X to Y (remove X's facet first), (2) User wants to clear existing filters/groupings, (3) Reducing constraints. Use mpty array [] for no removals."
        },
        "toggle_filters": {
            "type": "array",
            "description": "List of filters to add/remove. Can include both predefined search filters and specific date range configurations. If the filter is already applied, removes it. Use [] for no filters",
            "items": {
                "anyOf": [
                    {
                        "type": "string",
                        "description": "The technical name of a predefined filter (e.g., 'my_favorites' or 'active'). Must match a name in the menu's search view's available filters"
                    },
                    {
                        "type": "object",
                        "description": "Custom date range configuration",
                        "properties": {
                            "field_name": {
                                "type": "string",
                                "description": "The technical name of the date field (e.g., 'date_order')"
                            },
                            "selected_periods": {
                                "type": "array",
                                "description": "List of relative periods (e.g., ['month', 'year-1'])",
                                "items": {
                                    "type": "string",
                                    "description": "Pattern: 'month', 'year', 'month±N', 'year±N', 'first_quarter', 'second_quarter', 'third_quarter', 'fourth_quarter' or 'custom_...' (where N restrictions and custom_... patterns are found in the menu's search view)"
                                }
                            }
                        },
                        "required": ["field_name", "selected_periods"]
                    }
                ]
            }
        },
        "toggle_groupbys": {
            "type": "array",
            "description": "Ordered list of fields or date intervals objects to group by to add/remove. Prefer fields in the menu's search views' groupby fields. Any other groupable field can be used. For date groupbys, each interval is toggled on/off independently. To switch from one interval to another (e.g., week to month), use remove_facets to remove the existing date groupby facet first. Use [] for no grouping",
            "items": {
                "anyOf": [
                    {
                        "type": "string",
                        "description": "The technical name of the field to group by"
                    },
                    {
                        "type": "object",
                        "description": "Date interval grouping object",
                        "properties": {
                            "field_name": {
                                "type": "string",
                                "description": "The technical name of the date field"
                            },
                            "intervals": {
                                "type": "array",
                                "description": "List of intervals to group by",
                                "items": {
                                    "type": "string",
                                    "description": "Interval name",
                                    "enum": ["day", "week", "month", "quarter", "year"]}
                            }
                        },
                        "required": ["field_name", "intervals"]
                    }
                ]
            }
        },
        "apply_searches": {
            "type": "array",
            "description": "Simulates typing into the search bar. Use this for quick text lookups on specific fields. Use [] for no search",
            "items": {
                "type": "object",
                "properties": {
                    "search_field": {
                        "type": "string",
                        "description": "Technical name of the field to search (e.g., 'partner_id', 'name'). Must be a searchable field"
                    },
                    "value": {
                        "type": "string",
                        "description": "Text value to search for"
                    }
                },
                "required": ["search_field", "value"]
            }
        },
        "measures": {
            "type": "array",
            "items": {"type": "string"},
            "description": "List of measures to be activated. Can be multiple items in pivot view but only one item in graph view."
        },
        "mode": {
            "type": "string",
            "description": "For graph view: Chart type: 'bar' for comparisons, 'line' for trends, 'pie' for proportions"
        },
        "order": {
            "type": "string",
            "description": "For graph view: Sort direction: 'DESC' for highest first, 'ASC' for lowest first"
        },
        "stacked": {
            "type": "boolean",
            "description": "For graph view: Stack bars/areas on top of each other (default: false)"
        },
        "cumulated": {
            "type": "boolean",
            "description": "For graph view: Show cumulative values over time (default: false)"
        },
        "custom_domain": {
            "type": "string",
            "description": "Optional odoo domain, to use when search view elements are insufficient."
        },
        "switch_view_type": {
            "type": "string",
            "description": "The view type to switch to. Must be one of the available view types. Empty string for no switch."
        }
    },
    "required": ["model_name"]
}

{
    "type": "object",
    "properties": {
        "model_name": {
            "type": "string",
            "description": "Technical model name (e.g., 'sale.order', 'product.product', 'res.partner')"
        },
        "domain": {
            "type": "string",
            "description": "Search domain. Use an empty list to match all records"
        },
        "fields": {
            "type": "array",
            "description": "list of fields to fetch. DEFAULT: display_name only — pass explicit field names to retrieve more (do NOT omit to get all fields).",
            "items": {
                "type": "string",
                "description": "Technical name of a field available on the model. Related field paths (eg. 'partner_id.name') are not allowed"
            }
        },
        "offset": {
            "type": "number",
            "description": "number of results to skip (default 0). Use with `limit` to paginate."
        },
        "limit": {
            "type": "number",
            "description": "max rows to return (default 50, max 200). Use `offset` to paginate."
        },
        "order": {
            "type": "string",
            "description": "Optional 'order by' specification. This field should have the form `field_name DESC` (or ASC for ascending order)"
        }
    },
    "required": ["model_name", "domain"]
}

{
    "type": "object",
    "properties": {
        "model_name": {
            "type": "string",
            "description": "Technical model name, 'ir.attachment' or the model holding the binary field"
        },
        "record_ids": {
            "type": "array",
            "description": "Record IDs to read the content of, at most 5 at a time",
            "items": {"type": "integer"}
        },
        "field_name": {
            "type": "string",
            "description": "Technical name of the binary field to read. It is not required for 'ir.attachment' records"
        }
    },
    "required": ["model_name", "record_ids"]
}

{
    "type": "object",
    "properties": {
        "model_name": {
            "type": "string",
            "description": "Technical model name of the searched records (e.g., 'product.product', 'slide.channel')"
        },
        "records_to_preview": {
            "type": "array",
            "description": "The records array that are needed to be previewed.",
            "items": {
                "type": "object",
                "properties": {
                    "id": {
                        "type": "integer",
                        "description": "The record ID"
                    }
                },
                "required": ["id"]
            }
        },
        "header": {
            "type": "string",
            "description": "Group heading. Include only when making multiple calls for one response; Never use it for a single-group message response."
        }
    },
    "required": ["model_name", "records_to_preview"]
}

{
    "type": "object",
    "properties": {
        "model_name": {
            "type": "string",
            "description": "Technical model name (e.g., 'sale.order', 'product.product', 'res.partner')"
        },
        "domain": {
            "type": "string",
            "description": "Search domain. Use an empty list to match all records"
        },
        "groupby": {
            "type": "array",
            "description": "list of groupby descriptions by which the records will be grouped. A groupby description is either a field (then it will be grouped by that field) or a string `'field:granularity'`. Right now, the only supported granularities are `'day'`, `'week'`, `'month'`, `'quarter'` or `'year'`, and they only make sense for date/datetime fields. Additionally integer date parts are also supported: `'year_number'`, `'quarter_number'`, `'month_number'`, `'iso_week_number'`, `'day_of_year'`, `'day_of_month'`, 'day_of_week', 'hour_number', 'minute_number' and 'second_number'.",
            "items": {
                "type": "string"
            }
        },
        "aggregates": {
            "type": "array",
            "description": "list of aggregates specification. Each element is `'field:agg'` (aggregate field with aggregation function `'agg'`). The possible aggregation functions are the ones provided by `PostgreSQL`, `'count_distinct'` with the expected meaning and `'recordset'` to act like `'array_agg'` converted into a recordset. Only stored fields can be used for aggregation.",
            "items": {
                "type": "string"
            }
        },
        "having": {
            "type": "string",
            "description": "A domain where the valid 'fields' are the aggregates. The provided field names must exist in the aggregate elements. Example `[('amount_total:sum', '>', 1000)]`"
        },
        "offset": {
            "type": "number",
            "description": "optional number of groups to skip. Use with `limit` to paginate."
        },
        "limit": {
            "type": "number",
            "description": "max groups to return (default 100, max 500). Use `offset` to paginate."
        },
        "order": {
            "type": "string",
            "description": "optional 'order by' specification, for overriding the natural sort ordering of the groups. The order must be a valid PostgreSQL group by, it must use a valid `aggregate` or `groupby element. The provided fields must exist in the group by or aggregate elements. DO NOT make up any field name. i.e. For an aggregate `amount_total:sum`, the valid order is `amount_total:sum`."
        }
    },
    "required": ["model_name", "domain"]
}

Computes exact date/datetime values for relative date expressions. Can traverse years, quarters, months, weeks, and days, and anchor to specific weekdays or times.
**Returns**: - Date fields: 'YYYY-MM-DD' (in user timezone) - Datetime fields: 'YYYY-MM-DD HH:MM:SS' (in UTC)
**Core Concepts**:
1. **Operations**: Sequential transformations applied to current time - navigate: Move through time periods * Required: type="navigate", period (minute/hour/day/week/month/quarter/year), offset (negative=past, positive=future) * Optional: boundary ('start' or 'end' of period) - find_previous: Search backward for specific weekday * Required: type="find_previous", weekday (0-6) * Note: boundary not supported - use pin for time adjustment - find_next: Search forward for specific weekday * Required: type="find_next", weekday (0-6) * Note: boundary not supported - use pin for time adjustment
2. **Pin**: Final anchoring to specific position (applied after all operations) - day: Lock to specific day (integer 1-31) or weekday occurrence (object with weekday 0-6, occurrence 1-5) - time: Set specific time ('HH:MM' or 'HH:MM:SS')
**Examples**:
# "Yesterday at midnight" {"operations": [{"type": "navigate", "period": "day", "offset": -1, "boundary": "start"}]}
# "Next Friday at 5 PM" {"operations": [{"type": "find_next", "weekday": 4}], "pin": {"time": "17:00"}}
# "Start of last week" {"operations": [{"type": "navigate", "period": "week", "offset": -1, "boundary": "start"}]}
# "First Monday of last month" {"operations": [{"type": "navigate", "period": "month", "offset": -1, "boundary": "start"}], "pin": {"day": {"weekday": 0, "occurrence": 1}}}
# "3rd week of 2 quarters ago" {"operations": [{"type": "navigate", "period": "quarter", "offset": -2, "boundary": "start"}, {"type": "navigate", "period": "week", "offset": 2, "boundary": "start"}]}
# "Last Monday at 5 PM" {"operations": [{"type": "find_previous", "weekday": 0}], "pin": {"time": "17:00"}}
# "5 days into last month" {"operations": [{"type": "navigate", "period": "month", "offset": -1, "boundary": "start"}, {"type": "navigate", "period": "day", "offset": 5}]}
# "2nd week of 3 years ago" {"operations": [{"type": "navigate", "period": "year", "offset": -3, "boundary": "start"}, {"type": "navigate", "period": "week", "offset": 1, "boundary": "start"}]}
# "10 days before end of last quarter" {"operations": [{"type": "navigate", "period": "quarter", "offset": -1, "boundary": "end"}, {"type": "navigate", "period": "day", "offset": -10}]}
Note: Weekday values are 0=Monday through 6=Sunday. Weeks start Monday (ISO 8601).

{
    "type": "object",
    "properties": {
        "model_name": {
            "type": "string",
            "description": "Technical model name (e.g., 'sale.order')"
        },
        "field_name": {
            "type": "string",
            "description": "Date or datetime field name (e.g., 'date_order', 'create_date')"
        },
        "operations": {
            "type": "array",
            "description": "Sequential operations to apply. Each operation transforms the working datetime.",
            "items": {
                "anyOf": [
                    {
                        "type": "object",
                        "properties": {
                            "type": {
                                "type": "string",
                                "enum": ["navigate"],
                                "description": "Navigate through time periods"
                            },
                            "period": {
                                "type": "string",
                                "enum": ["minute", "hour", "day", "week", "month", "quarter", "year"],
                                "description": "Time period to navigate"
                            },
                            "offset": {
                                "type": "integer",
                                "description": "Number of periods to move. Negative = past, positive = future. Default: 0"
                            },
                            "boundary": {
                                "type": "string",
                                "enum": ["start", "end"],
                                "description": "Navigate to start or end of period (optional)"
                            }
                        },
                        "required": ["type", "period"]
                    },
                    {
                        "type": "object",
                        "properties": {
                            "type": {
                                "type": "string",
                                "enum": ["find_previous", "find_next"],
                                "description": "Find previous or next occurrence of a weekday"
                            },
                            "weekday": {
                                "type": "integer",
                                "description": "Target weekday. 0=Monday, 1=Tuesday, 2=Wednesday, 3=Thursday, 4=Friday, 5=Saturday, 6=Sunday"
                            }
                        },
                        "required": ["type", "weekday"]
                    }
                ]
            }
        },
        "pin": {
            "type": "object",
            "description": "Final anchoring applied after all operations.",
            "properties": {
                "day": {
                    "anyOf": [
                        {
                            "type": "integer",
                            "description": "Day of month (1-31)"
                        },
                        {
                            "type": "object",
                            "description": "Weekday selector",
                            "properties": {
                                "weekday": {
                                    "type": "integer",
                                    "description": "Weekday (0=Monday, 6=Sunday)"
                                },
                                "occurrence": {
                                    "type": "integer",
                                    "description": "Nth occurrence in month (1-5). E.g., 2 for '2nd Monday'"
                                }
                            },
                            "required": ["weekday"]
                        }
                    ]
                },
                "time": {
                    "type": "string",
                    "pattern": "^([01]?[0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9])?$",
                    "description": "Time in 'HH:MM' or 'HH:MM:SS' format (24-hour)"
                }
            },
            "required": []
        }
    },
    "required": ["model_name", "field_name"]
}

{
    "type": "object",
    "properties": {
        "explanation": {
            "type": "string",
            "description": "An explanation of the tool call. It MUST end asking for user's CONFIRMATION."
        },
        "preview_menus": {
            "type": "array",
            "description": "An array containing the menus to open to show the preview of created records",
            "items": {
                "type": "object",
                "description": "A mapping between the record model and the menu to open.",
                "properties": {
                    "model_name": {
                        "type": "string",
                        "description": "The name of the model linked to the menu"
                    },
                    "menu_id": {
                        "type": "integer",
                        "description": "The id of the menu to call to show the preview. Always the default view of the model."
                    }
                },
                "required": ["model_name", "menu_id"]
            }
        },
        "updates": {
            "type": "array",
            "description": "list of updates to do",
            "items": {
                "type": "object",
                "properties": {
                    "model_name": {
                        "type": "string",
                        "description": "technical name of the model (eg. 'mail.message')"
                    },
                    "domain": {
                        "type": "string",
                        "description": "Odoo domain of the records of the given model name to update. Cannot be a dummy truthy domain (e.g. '[]', 'True'). To update all records, pass a domain that matches all records."
                    },
                    "changes": {
                        "type": "array",
                        "description": "list of objects of changes. Objects must either use value or x2m_commands, but not both. x2m_commands can only be used with a one2many or a many2many field",
                        "items": {
                            "type": "object",
                            "properties": {
                                "field": {
                                    "type": "string",
                                    "description": "technical name of the field to update"
                                },
                                "value": {
                                    "anyOf": [
                                        { "type": "string" },
                                        { "type": "number" },
                                        { "type": "boolean" },
                                        { "type": "null" }
                                    ],
                                    "description": "The new value to assign to the field. Must be 'null' if the field is updated using a x2m command. Cannot be used to create records"
                                },
                                "x2m_commands": {
                                    "type": "string",
                                    "description": "List of commands to apply to the field. Can only be used on a one2many or many2many field"
                                }
                            },
                            "description": "Change to apply to a field",
                            "required": ["field"]
                        }
                    }
                },
                "required": ["model_name", "domain", "changes"]
            }
        }
    },
    "required": ["explanation", "preview_menus", "updates"]
}

{
    "type": "object",
    "properties": {
        "explanation": {
            "type": "string",
            "description": "An explanation of the tool call. It MUST end with a question asking for user's CONFIRMATION."
        },
        "model_name": {
            "type": "string",
            "description": "technical name of the model (i.e. 'mail.message')"
        },
        "preview_menu_id": {
            "type": "integer",
            "description": "The id of a menu linked to the model specified in `model_name`, used to generate the preview link for created records. It must be a valid menu for that model, preferably its default view menu. This field should almost always be filled — only leave it empty if the model has absolutely no associated menu."
        },
        "values": {
            "type": "array",
            "description": "list of records to create along with their fields",
            "items": {
                "type": "object",
                "properties": {
                    "field_values": {
                        "type": "array",
                        "description": "list of values to assign to the fields of the record",
                        "items": {
                            "type": "object",
                            "properties": {
                                "field": {
                                    "type": "string",
                                    "description": "technical name of the field"
                                },
                                "value": {
                                    "anyOf": [
                                        { "type": "string" },
                                        { "type": "number" },
                                        { "type": "boolean" },
                                        { "type": "null" }
                                    ],
                                    "description": "The value to assign to the field. Use 'null' if the field is initialized using a x2m command"
                                },
                                "x2m_link_ids": {
                                    "anyOf": [
                                        {
                                            "type": "integer",
                                            "description": "The id of a record to link"
                                        },
                                        {
                                            "type": "array",
                                            "description": "A list of existing records ids to link.",
                                            "items": {
                                                "type": "integer",
                                                "description": "The id of an existing record."
                                            }
                                        },
                                        { "type": "null"}
                                    ]
                                }
                            },
                            "description": "Values to apply to the newly created record. field_values is a list of x2m_commands if the field is a one2many or a many2many, a value otherwise",
                            "required": ["field"]
                        }
                    }
                },
                "required": ["field_values"]
            }
        }
    },
    "required": ["explanation", "model_name", "values"]
}

{
    "properties": {
        "prompt": {
            "type": "string",
            "description": "The prompt that will be sent to the LLM to generate the image with the description that the user has specified. Make sure to specify how each attachment if any will be used in the generation process."
        },
        "images_paths": {
            "type": "array",
            "items": {"type": "string"},
            "description": "A list of paths of images that should be used for image generation."
        },
        "image_title": {
            "type": "string",
            "description": "A descriptive name for the generated image"
        },
        "feedback": {
            "type": "string",
            "description": "A message that will be shown to the user after the image is generated successfully to ask for their feedback. The feedback should be short and concise and should give the user a hint on what else can be changed in the image. For example, if the user asked for a picture of a cat, the feedback could be 'Here is your picture of a cat. Let me know if you want me to change anything else (more cats, different pose, different background, ..)'. The feedback should be properly formatted HTML"
        },
        "aspect_ratio": {
            "type": "string",
            "description": "The aspect ratio to use for image generation. If not specified by the user, use the aspect ratio of the reference image (if any). Otherwise default to '1:1'."
        }
    },
    "required": ["prompt", "image_title", "feedback", "aspect_ratio"],
    "type": "object"
}

{
    "type": "object",
    "properties": {
        "query": {
            "type": "string",
            "description": "A comprehensive search query containing all necessary context to find a factual answer. Use specific names, dates, or technical terms so the search agent can work independently."
        },
        "retrieval_mode": {
            "type": "string",
            "enum": ["fact", "summary", "deep"],
            "description": "Controls the depth of results returned. Use 'fact' for simple lookups (addresses, dates, names), 'summary' for understanding a topic, and 'deep' for content generation or in-depth research requiring multiple perspectives and rich detail."
        },
        "context_hint": {
            "type": "string",
            "description": "Optional. A short description of how the result will be used (e.g. 'writing a 800-word news article' or 'answering a quick user question'). Helps the search agent calibrate source selection and framing."
        }
    },
    "required": ["query", "retrieval_mode"]
}
